// Menu stores the information required for a standard menu.
// A menu can pop down from a MainMenu or could be a pop out menu.
type Menu struct {
	Label string
	Items []*MenuItem
}

// NewMenu creates a new menu given the specified label (to show in a MainMenu) and list of items to display.
func NewMenu(label string, items ...*MenuItem) *Menu {
	return &Menu{Label: label, Items: items}
}

// Refresh triggers a redraw of this menu in all windows where it is currently displayed.
// This should be called when menu items, icons, shortcuts, or other properties have been updated.
//
// Since: 2.5
func (m *Menu) Refresh() {
	app := CurrentApp()
	if app == nil {
		return
	}

	for _, win := range app.Driver().AllWindows() {
		if win.MainMenu() != nil {
			for _, menu := range win.MainMenu().Items {
				if menu == m {
					win.SetMainMenu(win.MainMenu())
					break
				}
			}
		}
	}
}

