package theme

import (
	"encoding/json"
	"image/color"

	"fyne.io/fyne/v2"
)

// jsonTheme implements fyne.Theme using data loaded from JSON
type jsonTheme struct {
	colors map[fyne.ThemeColorName]map[fyne.ThemeVariant]color.Color
	sizes  map[fyne.ThemeSizeName]float32
	fonts  map[string]fyne.Resource
}

// ThemeFromJSON creates a new Theme from JSON-encoded theme data.
// The JSON should contain "colors", "sizes", and "fonts" mappings.
// Returns an error if the JSON is invalid.
//
// Since: 2.5
func ThemeFromJSON(data []byte) (fyne.Theme, error) {
	var raw struct {
		Colors map[string]map[string]string  `json:"colors"` // colorName -> variant -> hex
		Sizes  map[string]float32            `json:"sizes"`  // sizeName -> value
		Fonts  map[string]string             `json:"fonts"`  // style -> path
	}

	if err := json.Unmarshal(data, &raw); err != nil {
		return nil, err
	}

	theme := &jsonTheme{
		colors: make(map[fyne.ThemeColorName]map[fyne.ThemeVariant]color.Color),
		sizes:  make(map[fyne.ThemeSizeName]float32),
		fonts:  make(map[string]fyne.Resource),
	}

	// Parse colors
	for colorName, variants := range raw.Colors {
		theme.colors[fyne.ThemeColorName(colorName)] = make(map[fyne.ThemeVariant]color.Color)
		for variant, hexColor := range variants {
			if c, err := parseHexColor(hexColor); err == nil {
				theme.colors[fyne.ThemeColorName(colorName)][fyne.ThemeVariant(variant)] = c
			}
		}
	}

	// Parse sizes
	for sizeName, value := range raw.Sizes {
		theme.sizes[fyne.ThemeSizeName(sizeName)] = value
	}

	// Fonts would require loading from paths - simplified here
	// Real implementation would use fyne.LoadResourceFromPath or similar

	return theme, nil
}

