package binding

import (
	"fmt"
	"sync"
)

// stringFormat is a String binding that formats its value using fmt.Sprintf
type stringFormat struct {
	base

	format  string
	sources []DataItem
	lock    sync.RWMutex
}

// BindingSprintf creates a new String binding that formats multiple source bindings using fmt.Sprintf.
// The format string follows the same rules as fmt.Sprintf, and sources are the data bindings to be formatted.
// The binding automatically updates whenever any of the source bindings change.
//
// Example:
//   name := binding.NewString()
//   age := binding.NewInt()
//   formatted := binding.BindingSprintf("Name: %s, Age: %d", name, age)
//
// Since: 2.5
func BindingSprintf(format string, sources ...DataItem) String {
	s := &stringFormat{
		format:  format,
		sources: sources,
	}

	// Listen to all source bindings
	listener := NewDataListener(func() {
		s.trigger()
	})

	for _, source := range sources {
		if source != nil {
			source.AddListener(listener)
		}
	}

	return s
}

func (s *stringFormat) Get() (string, error) {
	s.lock.RLock()
	defer s.lock.RUnlock()

	// Collect values from all sources
	values := make([]interface{}, 0, len(s.sources))
	for _, source := range s.sources {
		if source == nil {
			values = append(values, nil)
			continue
		}

		// Try to get the value based on the type of binding
		switch src := source.(type) {
		case String:
			if val, err := src.Get(); err == nil {
				values = append(values, val)
			} else {
				values = append(values, "")
			}
		case Int:
			if val, err := src.Get(); err == nil {
				values = append(values, val)
			} else {
				values = append(values, 0)
			}
		case Float:
			if val, err := src.Get(); err == nil {
				values = append(values, val)
			} else {
				values = append(values, 0.0)
			}
		case Bool:
			if val, err := src.Get(); err == nil {
				values = append(values, val)
			} else {
				values = append(values, false)
			}
		default:
			// For other types, use empty string
			values = append(values, "")
		}
	}

	return fmt.Sprintf(s.format, values...), nil
}

