9|// stringFormat is a String binding that formats its value using fmt.Sprintf
10|type stringFormat struct {
11|	base
12|	
13|	format  string
14|	sources []DataItem
15|}
16|
17|// NewSprintf creates a new String binding that formats multiple source bindings using fmt.Sprintf.
18|// The format string follows the same rules as fmt.Sprintf, and sources are the bindings to be formatted.
19|// 
20|// Setting a value will attempt to parse it back using fmt.Sscanf and update the source bindings.
21|// When any source binding changes, the formatted string is automatically recalculated.
22|//
23|// Since: 2.5
24|func NewSprintf(format string, sources ...DataItem) String {
25|	s := &stringFormat{
26|		format:  format,
27|		sources: sources,
28|	}
29|	
30|	// Listen to all source bindings for changes
31|	listener := NewDataListener(func() {
32|		s.trigger()
33|	})
34|	
35|	for _, source := range sources {
36|		if source != nil {
37|			source.AddListener(listener)
38|		}
39|	}
40|	
41|	return s
42|}
