52|func (s *stringFormat) Get() (string, error) {
53|	values := make([]interface{}, 0, len(s.sources))
54|	
55|	for _, source := range s.sources {
56|		if source == nil {
57|			values = append(values, nil)
58|			continue
59|		}
60|		
61|		// Type assert to extract the actual value
62|		switch typed := source.(type) {
63|		case String:
64|			if val, err := typed.Get(); err == nil {
65|				values = append(values, val)
66|			} else {
67|				values = append(values, "")
68|			}
69|		case Bool:
70|			if val, err := typed.Get(); err == nil {
71|				values = append(values, val)
72|			} else {
73|				values = append(values, false)
74|			}
75|		case Int:
76|			if val, err := typed.Get(); err == nil {
77|				values = append(values, val)
78|			} else {
79|				values = append(values, 0)
80|			}
81|		case Float:
82|			if val, err := typed.Get(); err == nil {
83|				values = append(values, val)
84|			} else {
85|				values = append(values, 0.0)
86|			}
87|		case Untyped:
88|			if val, err := typed.Get(); err == nil {
89|				values = append(values, val)
90|			} else {
91|				values = append(values, nil)
92|			}
93|		default:
94|			// Unknown type, use nil
95|			values = append(values, nil)
96|		}
97|	}
98|	
99|	return fmt.Sprintf(s.format, values...), nil
100|}
