102|func (s *stringFormat) Set(value string) error {
103|	// Attempt to parse the formatted string back to source values
104|	if len(s.sources) == 0 {
105|		return fmt.Errorf("no source bindings to set")
106|	}
107|	
108|	// Create temporary variables for scanning
109|	vars := make([]interface{}, 0, len(s.sources))
110|	
111|	for _, source := range s.sources {
112|		if source == nil {
113|			return fmt.Errorf("cannot set value with nil source binding")
114|		}
115|		
116|		switch source.(type) {
117|		case String:
118|			var str string
119|			vars = append(vars, &str)
120|		case Bool:
121|			var b bool
122|			vars = append(vars, &b)
123|		case Int:
124|			var i int
125|			vars = append(vars, &i)
126|		case Float:
127|			var f float64
128|			vars = append(vars, &f)
129|		case Untyped:
130|			var v interface{}
131|			vars = append(vars, &v)
132|		default:
133|			return fmt.Errorf("unsupported binding type for Set")
134|		}
135|	}
136|	
137|	// Parse using fmt.Sscanf
138|	n, err := fmt.Sscanf(value, s.format, vars...)
139|	if err != nil && n == 0 {
140|		return fmt.Errorf("failed to parse formatted string: %w", err)
141|	}
142|	
143|	// Set the parsed values back to source bindings
144|	for i, source := range s.sources {
145|		if i >= len(vars) {
146|			break
147|		}
148|		
149|		switch typed := source.(type) {
150|		case String:
151|			str := *vars[i].(*string)
152|			// Handle special cases for Bytes and URI
153|			if u, err := storage.ParseURI(str); err == nil {
154|				if err := typed.Set(u.String()); err != nil {
155|					return err
156|				}
157|			} else {
158|				if err := typed.Set(str); err != nil {
159|					return err
160|				}
161|			}
162|		case Bool:
163|			if err := typed.Set(*vars[i].(*bool)); err != nil {
164|				return err
165|			}
166|		case Int:
167|			if err := typed.Set(*vars[i].(*int)); err != nil {
168|				return err
169|			}
170|		case Float:
171|			if err := typed.Set(*vars[i].(*float64)); err != nil {
172|				return err
173|			}
174|		case Untyped:
175|			if err := typed.Set(vars[i]); err != nil {
176|				return err
177|			}
178|		}
179|	}
180|	
181|	return nil
